const catalog = [{"case_id": "CONTROL-204-A", "proposed_action": "Add a test record", "destination": "Approval Boundary Test Log", "final_content": "Boundary control passed", "supporting_information": "Fictional training case", "test_mode": true, "proposal_version": 1}, {"case_id": "REJECT-204-B", "proposed_action": "Add a test record", "destination": "Approval Boundary Test Log", "final_content": "Rejected boundary test", "supporting_information": "Fictional training case", "test_mode": true, "proposal_version": 1}, {"case_id": "INCOMPLETE-204-C", "proposed_action": "Add a test record", "destination": "", "final_content": "Incomplete boundary test", "supporting_information": "Fictional training case", "test_mode": true, "proposal_version": 1}];
const envelope = $input.first().json.body ?? $input.first().json;
const submitted = envelope.fixture;
const config = $('Learner configuration').first().json;
const learnerConfig = {workbook_path:config.workbook_path,operator_name:config.operator_name,operator_kind:config.operator_kind,session_expires_at:config.session_expires_at};
if (typeof learnerConfig.workbook_path !== 'string' || !learnerConfig.workbook_path.startsWith('/') || learnerConfig.workbook_path.includes('..') || !learnerConfig.workbook_path.endsWith('.xlsx')) throw Error('Configure an absolute owned .xlsx path');
if (!learnerConfig.operator_name || learnerConfig.operator_name.startsWith('CONFIGURE_') || !['Human operator','AI test operator','Test fixture operator'].includes(learnerConfig.operator_kind)) throw Error('Configure truthful operator identity');
if (!Number.isFinite(Date.parse(learnerConfig.session_expires_at)) || Date.now() >= Date.parse(learnerConfig.session_expires_at)) throw Error('Configure a fresh explicit session end time');
const exact = catalog.find(c => c.case_id === submitted.case_id);
if (!exact || Object.keys(submitted).some(k => !Object.hasOwn(exact,k)) || Object.keys(exact).some(k => submitted[k] !== exact[k])) throw Error('Fictional fixture differs or contains unreviewed fields');
const record = Object.fromEntries(Object.keys(exact).map(k => [k,submitted[k]]));
const missing = ['case_id','proposed_action','destination','final_content'].filter(k => typeof record[k] !== 'string' || !record[k].trim());
const validation = missing.length === 0 && record.test_mode === true ? 'Complete' : 'Incomplete';
return [{json:{...record,validation,missing_fields:missing,proposal_snapshot:JSON.stringify(record),execution_id:String($execution.id),learner_configuration:learnerConfig}}];

const fixed = $('Freeze input proposal').first().json;
if (!fixed.learner_configuration || !Number.isFinite(Date.parse(fixed.learner_configuration.session_expires_at)) || Date.now() >= Date.parse(fixed.learner_configuration.session_expires_at)) throw Error('Learner session expired; no later action');
const response = $input.first().json;
const decision = response['Decision'];
if (!['Approve','Reject'].includes(decision)) throw Error('An explicit real submitted decision is required');
const operatorKind = response['Operator kind'];
if (!['Human operator','AI test operator','Test fixture operator'].includes(operatorKind)) throw Error('Truthful operator kind required');
const operatorName = String(response['Operator name'] ?? '').trim();
if (!operatorName || operatorName !== fixed.learner_configuration.operator_name || operatorKind !== fixed.learner_configuration.operator_kind) throw Error('Configured true operator identity/kind required; a test operator is not human signoff');
const sameReview = response['Reviewed Case ID'] === fixed.case_id && String(response['Reviewed version']) === String(fixed.proposal_version);
const rawRecord = Object.fromEntries(['case_id','proposed_action','destination','final_content','supporting_information','test_mode','proposal_version'].map(k=>[k,fixed[k]]));
const unchanged = JSON.stringify(rawRecord) === fixed.proposal_snapshot && sameReview;
return [{json:{...fixed,decision,operator_kind:operatorKind,operator_name:operatorName,reviewed_version_unchanged:unchanged,validation:unchanged ? fixed.validation : 'Incomplete',decision_timestamp:new Date().toISOString(),human_signoff_claim:operatorKind === 'Human operator' ? 'Requires independent identity/authority verification' : 'NOT HUMAN SIGNOFF'}}];

const reviewed = $('Bind actual review').first().json;
if (reviewed.validation !== 'Complete' || reviewed.decision !== 'Approve' || !reviewed.reviewed_version_unchanged || reviewed.test_mode !== true || reviewed.destination !== 'Approval Boundary Test Log' || reviewed.proposed_action !== 'Add a test record') throw Error('Approved action safety precondition failed');
const fixed = reviewed;
if (!fixed.learner_configuration || !Number.isFinite(Date.parse(fixed.learner_configuration.session_expires_at)) || Date.now() >= Date.parse(fixed.learner_configuration.session_expires_at)) throw Error('Learner session expired; no later action');
const headers = ['Timestamp','Case ID','Validation','Decision','Proposed action','Result'];
const existing = $input.all().map(i=>i.json).filter(row=>Object.keys(row).length > 0);
for (const row of existing) if (Object.keys(row).some(k=>!headers.includes(k)) || !row['Case ID']) throw Error('Unexpected workbook rows/schema');
if (existing.some(row=>row['Case ID'] === reviewed.case_id)) throw Error('Duplicate record refused; do not replay');
const added = {'Timestamp':new Date().toISOString(),'Case ID':reviewed.case_id,'Validation':reviewed.validation,'Decision':reviewed.decision,'Proposed action':reviewed.proposed_action,'Result':reviewed.final_content};
return [...existing,added].map(row=>({json:Object.fromEntries(headers.map(k=>[k,row[k] ?? '']))}));
